function env(buf, a, d, curve = 1) { const na = Math.max(1, a * SR); for (let i = 0; i < buf.length; i++) { const t = i / SR; const e = i < na ? i / na : Math.exp(-(t - a) / d); buf[i] *= curve === 1 ? e : Math.pow(e, curve); } return buf; }
