const PAD = db(-6), BASS = db(-9), FOLEY = db(4);
const chordPad = (notes, t, dur, gain, opts = {}) => notes.forEach((s, i) => put(bus.mus, pad(NOTE(s), dur, opts.att ?? 1.6, opts.rel ?? 1.8, opts.bright ?? .7), t, gain * PAD, (i / (notes.length - 1 || 1)) * .7 - .35, bus.musSend, .55));
